// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.junit.jupiter.api.Test;

class TupleFunctionCallTest {
	@Test
	void replacementKeepsTheUnchangedChildOwnedByTheCall() {
		TupleFunctionCall call = new TupleFunctionCall();
		call.setURI("urn:rdf4j:test:tuple-function");
		Var guard = Var.of("guard");
		TupleExpr fallback = new SingletonSet();
		call.setFallback(fallback, guard, true);

		TupleExpr replacementFallback = new EmptySet();
		fallback.replaceWith(replacementFallback);
		assertSame(replacementFallback, call.getFallback());
		assertSame(call, replacementFallback.getParentNode());
		assertSame(guard, call.getArgumentGuard());
		assertSame(call, guard.getParentNode());

		Var replacementGuard = Var.of("replacement");
		guard.replaceWith(replacementGuard);
		call.setFallback(replacementFallback, replacementGuard, false);
		assertSame(replacementFallback, call.getFallback());
		assertSame(call, replacementFallback.getParentNode());
		assertSame(replacementGuard, call.getArgumentGuard());
		assertSame(call, replacementGuard.getParentNode());
		assertFalse(call.appendsActiveGraph());

		TupleFunctionCall clone = call.clone();
		assertEquals(call, clone);
		assertNotSame(call.getFallback(), clone.getFallback());
		assertNotSame(call.getArgumentGuard(), clone.getArgumentGuard());
		assertSame(clone, clone.getFallback().getParentNode());
		assertSame(clone, clone.getArgumentGuard().getParentNode());
		assertSame(call, call.getFallback().getParentNode());
		assertSame(call, call.getArgumentGuard().getParentNode());
	}
}
